import React, { useEffect, useState } from "react";
import { TabView, TabPanel } from "primereact/tabview";
import { useLocation } from "react-router-dom";

const tabViewStyle = {
    navContainer: {
        className: "mgb14", // applies to <ul>
    }
};

const renderTabs = (tabs) => {
    return tabs.map((tab) => (
        <TabPanel
            key={tab.name}
            header={<h6 className="text-uppercase bold-font">{tab.name}</h6>}
        >
            {tab.component}
        </TabPanel>
    ));
};


export default function DocTab({ meta }) {
    const [tabs, setTabs] = useState([]);
    const location = useLocation();
    
    // Force re-render when location changes by resetting tabs
    useEffect(() => {
        setTabs([]);
    }, [location.pathname]);

    useEffect(() => {
        // If meta is provided, use the new system
        if (meta) {
            const loadTabComponents = async () => {
                const loadedTabs = await Promise.all(
                    meta.tabs.map(async (tab) => {
                        try {
                            const ComponentModule = await tab.component();
                            const Component = ComponentModule.default || ComponentModule;
                            
                            // Validate that Component is a valid React component
                            if (typeof Component !== 'function' && typeof Component !== 'string') {
                                console.error(`Invalid component type for ${tab.name}:`, Component);
                                return {
                                    name: tab.name,
                                    component: <div>Invalid component type</div>
                                };
                            }
                            
                            return {
                                name: tab.name,
                                component: <Component />
                            };
                        } catch (error) {
                            console.error(`Failed to load tab component for ${tab.name}:`, error);
                            return {
                                name: tab.name,
                                component: <div>Failed to load component: {error.message}</div>
                            };
                        }
                    })
                );
                setTabs(loadedTabs);
            };

            loadTabComponents();
            return;
        }

        // If no meta is provided, set empty tabs
        setTabs([]);
    }, [location.pathname, meta]);

    return (
        <TabView pt={tabViewStyle}>
            {renderTabs(tabs)}
        </TabView>
    );
}